<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Carrito - TecnoStore</title><link rel="stylesheet" href="assets/style.css"></head><body><aside><div class="brand">🛒 TecnoStore</div><div class="user">👤 <?=htmlspecialchars($_SESSION['usuario_nombre'])?><span>Cliente</span></div><nav><a href="index.php">🛍️ Catálogo</a><a class="active" href="index.php?accion=carrito">🛒 Mi carrito (<?=$cantidadTotal?>)</a><a href="index.php#contacto">📞 Atención</a></nav><a class="logout" href="index.php?controller=login&action=logout">🚪 Cerrar sesión</a></aside><main><header><div><h1>Mi carrito</h1><p>Revisa los productos antes de realizar tu compra.</p></div><a class="btn" href="index.php">← Seguir comprando</a></header><?php if(!$carrito): ?><div class="empty-cart"><div>🛒</div><h2>Tu carrito está vacío</h2><p>Agrega productos tecnológicos desde el catálogo.</p><a class="btn" href="index.php">Ver productos</a></div><?php else: ?><div class="cart-list"><?php foreach($carrito as $item): ?><article class="cart-item"><div class="cart-icon"><?=htmlspecialchars($item['imagen'])?></div><div class="cart-info"><h2><?=htmlspecialchars($item['nombre'])?></h2><p>S/ <?=number_format($item['precio'],2)?> × <?=$item['cantidad']?></p></div><strong>S/ <?=number_format($item['precio']*$item['cantidad'],2)?></strong><a class="remove" href="index.php?accion=quitar_carrito&id=<?=$item['id']?>">🗑️ Quitar</a></article><?php endforeach; ?></div><div class="cart-summary"><span>Productos: <b><?=$cantidadTotal?></b></span><span>Total: <strong>S/ <?=number_format($total,2)?></strong></span><div><a class="btn secondary" href="index.php?accion=vaciar_carrito">Vaciar carrito</a><a class="btn" href="index.php?accion=pagar">🛍️ Comprar ahora</a></div></div><?php endif; ?></main></body></html>